const events = [
  { year:"1596", title:"Nașterea lui Petru Movilă", text:"Anul tradițional al nașterii sale, într-o familie boierească influentă din Moldova. Detaliile biografice timpurii sunt reconstruite din surse istorice ulterioare.", place:"sucz" },
  { year:"1607", title:"Moartea lui Simion Movilă", text:"Moartea tatălui său este un reper în istoria familiei Movilă și în contextul schimbărilor politice din regiune.", place:"sucz" },
  { year:"1620–1621", title:"Campaniile de la Țuțora și Hotin", text:"Petru Movilă este asociat în unele biografii cu evenimentele militare ale epocii. Detaliile participării sale trebuie verificate în surse biografice specializate.", place:"sucz" },
  { year:"1627", title:"Arhimandrit al Lavrei", text:"Petru Movilă a devenit arhimandrit al Lavrei Pecerska din Kiev, un centru monahal, cultural și tipografic important.", place:"lavra" },
  { year:"1631", title:"Școala Lavrei", text:"În apropierea Lavrei a fost organizată o școală care a contribuit la proiectul educațional susținut de Petru Movilă.", place:"lavra" },
  { year:"1632", title:"Unirea școlilor din Kiev", text:"Școala Lavrei și Școala Frăției din Kiev au fost reunite. Această instituție a devenit cunoscută ca un colegiu, iar statutul de academie aparține unei perioade ulterioare.", place:"podil" },
  { year:"1633", title:"Mitropolit al Kievului", text:"Petru Movilă a fost confirmat mitropolit al Kievului, consolidându-și rolul în viața bisericească și culturală a regiunii.", place:"kyiv" },
  { year:"1646–1647", title:"Ultimii ani și moștenirea", text:"În 1646 a fost publicat un important Trebnic asociat cu activitatea sa. Petru Movilă a murit în 1647, lăsând o moștenire educațională și religioasă durabilă.", place:"kyiv" }
];
const categoryColors = { education:"#9c7047", religion:"#7c343b", heritage:"#5e7966" };
let map, markers = {}, selectedPlaceId = "kyiv", activeFilter = "all", activeEvent = 0;

function updatePlacePanel(place) {
  selectedPlaceId = place.id;
  const visiblePlaces = places.filter(p => activeFilter === "all" || p.category === activeFilter);
  document.getElementById("panelIndex").textContent = `${String(Math.max(1, visiblePlaces.findIndex(p=>p.id===place.id)+1)).padStart(2,"0")} / ${String(visiblePlaces.length).padStart(2,"0")}`;
  document.getElementById("placeCategory").textContent = place.categoryLabel;
  document.getElementById("placeTitle").textContent = place.title;
  document.getElementById("placePeriod").textContent = place.period;
  document.getElementById("placeDescription").textContent = place.description;
  document.getElementById("placeNote").textContent = place.note;
}
function selectPlace(id, zoom = 11) {
  const place = places.find(p => p.id === id);
  if (!place) return;
  updatePlacePanel(place);
  if (map) map.flyTo([place.lat, place.lng], zoom, { duration: .65 });
  if (markers[id]) markers[id].openPopup();
}
function markerIcon(category) {
  return L.divIcon({ className:"", html:`<div class="custom-marker" style="background:${categoryColors[category] || "#7c343b"}"></div>`, iconSize:[15,15], iconAnchor:[7,7], popupAnchor:[0,-8] });
}
function renderMarkers() {
  if (!map) return;
  Object.values(markers).forEach(marker => map.removeLayer(marker));
  markers = {};
  const visible = places.filter(p => activeFilter === "all" || p.category === activeFilter);
  visible.forEach(place => {
    const marker = L.marker([place.lat, place.lng], { icon:markerIcon(place.category), title:place.title, alt:place.title });
    marker.bindPopup(`<strong>${place.title}</strong><br>${place.period}<br><span>${place.categoryLabel}</span><br><a href="#locuri" data-popup-place="${place.id}">${currentLanguage === "ru" ? "Подробнее" : currentLanguage === "uk" ? "Докладніше" : "Află mai multe"} →</a>`);
    marker.on("click", () => updatePlacePanel(place));
    marker.addTo(map);
    markers[place.id] = marker;
  });
  document.querySelectorAll(".filter-button").forEach(btn => btn.classList.toggle("active", btn.dataset.filter === activeFilter));
  const current = visible.find(p => p.id === selectedPlaceId) || visible[0];
  if (current) updatePlacePanel(current);
  document.getElementById("panelIndex").textContent = `01 / ${String(visible.length).padStart(2,"0")}`;
}
function initMap() {
  const mapElement = document.getElementById("map");
  if (!mapElement) return;
  if (!window.L) {
    mapElement.innerHTML = `<div class="map-error">${currentLanguage === "ru" ? "Не удалось загрузить карту. Проверьте подключение к интернету и обновите страницу." : currentLanguage === "uk" ? "Не вдалося завантажити мапу. Перевірте підключення до інтернету й оновіть сторінку." : "Harta nu s-a putut încărca. Verifică conexiunea la internet și reîncarcă pagina."}</div>`;
    return;
  }
  map = L.map("map", { scrollWheelZoom:false }).setView([49.4, 28.2], 5);
  L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png", {
    maxZoom:19, attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a> contributors'
  }).addTo(map);
  map.on("popupopen", event => {
    const link = event.popup.getElement()?.querySelector("[data-popup-place]");
    if (link) link.addEventListener("click", e => {
      e.preventDefault();
      const id = link.dataset.popupPlace;
      selectPlace(id, 13);
      document.getElementById("locuri").scrollIntoView({behavior:"smooth"});
    });
  });
  renderMarkers();
  setTimeout(() => map.invalidateSize(), 150);
}
function renderTimeline() {
  const track = document.getElementById("timelineTrack");
  track.innerHTML = "";
  events.forEach((event, index) => {
    const button = document.createElement("button");
    button.className = `timeline-point${index === activeEvent ? " active" : ""}`;
    button.type = "button";
    button.innerHTML = `<strong>${event.year}</strong><span>${event.title}</span>`;
    button.setAttribute("aria-pressed", String(index === activeEvent));
    button.addEventListener("click", () => chooseEvent(index));
    track.appendChild(button);
  });
  document.getElementById("timelineCount").textContent = `${String(activeEvent+1).padStart(2,"0")} — ${String(events.length).padStart(2,"0")}`;
  const event = events[activeEvent];
  document.getElementById("detailYear").textContent = event.year;
  document.getElementById("detailTitle").textContent = event.title;
  document.getElementById("detailText").textContent = event.text;
  document.getElementById("detailMapLink").onclick = () => selectPlace(event.place, 12);
}
function chooseEvent(index) {
  activeEvent = (index + events.length) % events.length;
  renderTimeline();
  const event = events[activeEvent];
  if (map) selectPlace(event.place, 11);
}
document.addEventListener("DOMContentLoaded", () => {
  initMap();
  renderTimeline();
  document.querySelectorAll(".filter-button").forEach(btn => btn.addEventListener("click", () => {
    activeFilter = btn.dataset.filter;
    renderMarkers();
  }));
  document.getElementById("resetMap").addEventListener("click", () => {
    activeFilter = "all";
    renderMarkers();
    if (map) map.flyTo([49.4, 28.2], 5, { duration:.65 });
  });
  document.getElementById("nextPlace").addEventListener("click", () => {
    const visible = places.filter(p => activeFilter === "all" || p.category === activeFilter);
    if (!visible.length) return;
    const index = visible.findIndex(p => p.id === selectedPlaceId);
    selectPlace(visible[(index + 1) % visible.length].id, 11);
  });
  document.getElementById("timelinePrev").addEventListener("click", () => chooseEvent(activeEvent - 1));
  document.getElementById("timelineNext").addEventListener("click", () => chooseEvent(activeEvent + 1));
  document.querySelectorAll("[data-place]").forEach(button => button.addEventListener("click", () => {
    const id = button.dataset.place;
    document.getElementById("harta").scrollIntoView({ behavior:"smooth" });
    setTimeout(() => selectPlace(id, 12), 350);
  }));
  const menuToggle = document.getElementById("menuToggle");
  const nav = document.getElementById("nav");
  menuToggle.addEventListener("click", () => {
    const open = nav.classList.toggle("open");
    menuToggle.setAttribute("aria-expanded", String(open));
    menuToggle.textContent = open ? "×" : "☰";
  });
  nav.querySelectorAll("a").forEach(link => link.addEventListener("click", () => {
    nav.classList.remove("open");
    menuToggle.setAttribute("aria-expanded", "false");
    menuToggle.textContent = "☰";
  }));
  const sections = [...document.querySelectorAll("main section[id]")];
  const observer = new IntersectionObserver(entries => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        nav.querySelectorAll("a").forEach(a => a.classList.toggle("active", a.getAttribute("href") === `#${entry.target.id}`));
      }
    });
  }, { rootMargin:"-35% 0px -55% 0px" });
  sections.forEach(section => observer.observe(section));
});


